int licznik = 0;
int liczba = 0;

int minimum = 1023;
int maksimum = 0;

int jasnosc = 0;

void Znak(int iNumer) {
  digitalWrite(8, ((iNumer == 0) || (iNumer == 1) || (iNumer == 7)) ? HIGH : LOW);

  switch (iNumer) {
    case 0: PORTD = 0b00000000; break;
    case 1: PORTD = 0b11100100; break;
    case 2: PORTD = 0b11000000; break;
    case 3: PORTD = 0b11110000; break;
    case 4: PORTD = 0b11100100; break;
    case 5: PORTD = 0b10110000; break;
    case 6: PORTD = 0b10010000; break;
    case 7: PORTD = 0b11100000; break;
    case 8: PORTD = 0b10000000; break;
    case 9: PORTD = 0b10100000; break;
    default: PORTD = 0b11011000; break;
  }
}

void setup() {
  for (int i = 2; i < 9; i++) {
    pinMode(i, OUTPUT);
  }

  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  delay(1000);

  int odczyt = analogRead(A0);

  minimum = odczyt;
  maksimum = odczyt;
}

void loop() {

  // Wyświetlanie aktualnej wartości

  digitalWrite(11, LOW);
  Znak(liczba % 10);
  digitalWrite(10, HIGH);
  delay(2);

  digitalWrite(10, LOW);
  Znak((liczba / 10) % 10);
  digitalWrite(11, HIGH);
  delay(2);

  // Aktualizacja pomiaru
  if (licznik++ >= 100) {

    int surowaJasnosc = analogRead(A0);

    // Aktualizacja MIN
    if (surowaJasnosc < minimum) {
      minimum = surowaJasnosc;
    }

    // Aktualizacja MAX
    if (surowaJasnosc > maksimum) {
      maksimum = surowaJasnosc;
    }

    // Przeliczenie pomiaru na zakres 0-99
    if (maksimum != minimum) {
      jasnosc = (99L * (surowaJasnosc - minimum)) /
                (maksimum - minimum);
    } else {
      jasnosc = 0;
    }

    liczba = constrain(jasnosc, 0, 99);

    licznik = 0;
  }
}
